// Assemble all data for publishing
const titleData = JSON.parse($node['Step 2: Title & Hooks (GPT-4o)'].json.choices[0].message.content);
const blogData = JSON.parse($node['Step 4: Blog Body (Sonnet 4.6)'].json.content[0].text);
const videoId = $node['Webhook Trigger'].json.body.video_id;

// Extract hero image and upload to R2 via local API
const imagenResponse = $node['Step 5: Hero Image (Imagen 3)'].json;
let heroImageUrl = '';
try {
  if (imagenResponse.predictions && imagenResponse.predictions[0] && imagenResponse.predictions[0].bytesBase64Encoded) {
    const imageKey = `hero/${videoId}-${Date.now()}.png`;
    const localApiUrl = $env.LOCAL_API_TUNNEL_URL;
    const localApiKey = $env.LOCAL_API_KEY;

    if (localApiUrl && localApiKey) {
      const response = await fetch(`${localApiUrl}/upload-image`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-API-Key': localApiKey,
        },
        body: JSON.stringify({
          image_base64: imagenResponse.predictions[0].bytesBase64Encoded,
          key: imageKey,
          content_type: 'image/png',
        }),
      });
      if (response.ok) {
        const result = await response.json();
        heroImageUrl = result.url;
      }
    }
  } else if (imagenResponse.images && imagenResponse.images[0]) {
    heroImageUrl = imagenResponse.images[0];
  }
} catch (e) {
  // If hero image processing failed, use empty string — blog will handle gracefully
  heroImageUrl = '';
}

return [{
  json: {
    videoId,
    title: titleData.title,
    hook: titleData.hook,
    seoDesc: titleData.seo_description,
    heroImage: heroImageUrl,
    intro: blogData.intro,
    sections: blogData.sections,
    conclusion: blogData.conclusion,
    tags: blogData.tags,
    keywords: titleData.keywords
  }
}];
